--
-- Table structure for table `curriculum`
--

CREATE TABLE `curriculum` (
  `curriculumID` varchar(3) NOT NULL,
  `curriculumName` varchar(100) NOT NULL,
  `curriculumNameEN` varchar(150) DEFAULT NULL,
  `deptNameTH` varchar(100) DEFAULT NULL,
  `deptNameEN` varchar(100) DEFAULT NULL,
  `degreeLevel` varchar(100) DEFAULT NULL,
  `curriculumType` varchar(100) DEFAULT NULL,
  `highlights` text DEFAULT NULL,
  `whatWeLearn` text DEFAULT NULL,
  `insideKuse` text DEFAULT NULL,
  `jobOpportunities` text DEFAULT NULL,
  `careerPrivate` text DEFAULT NULL,
  `careerGovernment` text DEFAULT NULL,
  `Images` varchar(255) DEFAULT NULL,
  `shopPhoto` varchar(255) DEFAULT NULL,
  `pdfFiles` varchar(255) DEFAULT NULL,
  `adminID` int(11) DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT current_timestamp(),
  `updatedBy` int(11) DEFAULT NULL,
  `updatedAt` datetime DEFAULT NULL,
  `icon` varchar(50) DEFAULT 'fa-graduation-cap'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

