INSERT INTO `curriculum` (`curriculumID`, `curriculumName`, `curriculumNameEN`, `deptNameTH`, `deptNameEN`, `degreeLevel`, `curriculumType`, `highlights`, `whatWeLearn`, `insideKuse`, `jobOpportunities`, `careerPrivate`, `careerGovernment`, `Images`, `shopPhoto`, `pdfFiles`, `adminID`, `createdAt`, `updatedBy`, `updatedAt`, `icon`) VALUES
(' IE', 'สาขาวิชาวิศวกรรมอุตสาหการ', 'Bachelor of Engineering Program in Industrial Engineering', 'ภาควิชาวิศวกรรมเครื่องกลและการผลิต', 'Civil and Environmental Engineering (CEE)', 'ปริญญาตรี', 'หลักสูตรวิศวกรรมศาสตรบัณฑิต (วศ.บ.)', 'หลักสูตรนี้เน้นสร้าง \"นักพัฒนาระบบ\" ที่ไม่ได้ดูแค่เครื่องจักร แต่ดูองค์รวมทั้ง คน ข้อมูล และเครื่องจักร เพื่อเป้าหมาย 3 ประการ:\r\n\r\n 1.ประสิทธิภาพสูง: ทำงานได้รวดเร็ว ลดขั้นตอนที่ไม่จำเป็น\r\n 2.คุณภาพดี: ตรงตามความต้องการของลูกค้า\r\n 3.ต้นทุนต่ำที่สุด: แข่งขันได้ในเชิงธุรกิจ', 'พื้นฐานวิศวกรรม: การเขียนแบบ (Drawing) และกลศาสตร์ (Mechanics)\r\nการออกแบบเครื่องจักร: คำนวณความแข็งแรงและออกแบบชิ้นส่วนเครื่องกล\r\nพลังงานและความร้อน: ระบบปรับอากาศพลังงานทดแทนและวิศวะยานยนต์\r\nการควบคุมอัตโนมัติ: ระบบ Robot และการควบคุมด้วยคอมพิวเตอร์\r\nการบริหารการผลิต: การวางแผนผลิตในโรงงานและการควบคุมคุณภาพ\r\nทักษะงานช่าง (ปฏิบัติ): ฝึกงานโรงงานจริง ทั้งงานเชื่อม กลึง กัด ตัด ไส เจาะ', 'วัสดุและกระบวนการผลิต: เรียนรู้พื้นฐานของสิ่งของที่จะผลิตและเทคนิคในการสร้างขึ้นมา\r\n\r\n เศรษฐศาสตร์และการเงิน : หัวใจของ IE คือ \"ความคุ้มค่า\" จึงต้องคำนวณต้นทุนและกำไรเป็น\r\n\r\n การศึกษาเทคนิคและระบบการผลิต : เรียนรู้วิธีการทำให้สินค้าทุกชิ้นมีมาตรฐานเดียวกัน\r\n\r\n การจัดการและการดำเนินการผลิต : วางแผนภาพรวมของโรงงาน ตั้งแต่รับวัตถุดิบจนถึงส่งมอบสินค้า', 'วิศวกรอุตสาหการ (IE) เป็นสาขาที่ \"ยืดหยุ่น\" ที่สุดสาขาหนึ่ง เพราะทุกธุรกิจต้องการการลดต้นทุน และเพิ่มประสิทธิภาพ จึงทำงานได้หลากหลายเซกเตอร์', 'วิศวกรการผลิต\r\nวิศวกรควบคุมคุณภาพ (QA/QC)\r\nวิศวกรวางแผนการผลิต', 'กระทรวงอุตสาหกรรม\r\nกระทรวงพลังงาน กำกับดูแลมาตรฐาน\r\nอาจารย์/นักวิจัย', 'Images-1783523650081-161519379.jpg', 'shopPhoto-1783523650146-377577830.jpg', 'pdfFiles-1783873640633-957499807.pdf,pdfFiles-1783873640637-510624905.pdf,pdfFiles-1783873640644-157999441.pdf', 1, '2026-07-08 22:14:10', 1, '2026-08-04 11:45:57', 'fas fa-industry'),
('CEE', 'สาขาวิชาวิศวกรรมโยธา', 'Bachelor of Engineering Program in Civil Engineering', 'ภาควิชาวิศวกรรมโยธาและสิ่งแวดล้อม', 'Civil and Environmental Engineering (CEE)', 'ปริญญาตรี', 'หลักสูตรวิศวกรรมศาสตรบัณฑิต (วศ.บ.)', 'เรียนรู้ครอบคลุมทุกมิติของงานโยธา ตั้งแต่การสำรวจ ออกแบบโครงสร้าง ไปจนถึงเทคโนโลยีการก่อสร้างที่ทันสมัย พร้อมทำงานได้ทันทีหลังเรียนจบ', 'งานสำรวจและออกแบบโครงสร้าง\r\nงานทดสอบดินและออกแบบฐานราก\r\nงานออกแบบและก่อสร้างถนน\r\nการใช้เครื่องจักรในงานก่อสร้าง\r\nคอมพิวเตอร์ช่วยในงานวิศวกรรม (BIM/CAD)\r\nวิศวกรรมแหล่งน้ำและสิ่งแวดล้อม', ' หลักสูตรรับรองโดย สภาวิศวกร มีสิทธิ์สอบใบประกอบวิชาชีพ (กว.) แน่นอน\r\n\r\n ปริญญาบัตรจาก มหาวิทยาลัยเกษตรศาสตร์ มาตรฐานเดียวกับทุกวิทยาเขต\r\n\r\n สถิติการได้งานทำสูงถึง 90% และตรงสายงานมากกว่า 90%\r\n\r\n เครือข่ายศิษย์เก่าโยธาดงตาลที่เข้มแข็ง พร้อมช่วยเหลือด้านการทำงาน', '1. วิศวกรออกแบบและควบคุมงานในบริษัทเอกชนชั้นนำ\r\n\r\n2. รับราชการในหน่วยงานเกรด A เช่น กรมโยธาฯ, กรมทางหลวง, กรมชลประทาน\r\n\r\n3. ประกอบธุรกิจส่วนตัว ด้านการรับเหมาก่อสร้างและที่ปรึกษาโครงการ', 'วิศวกรออกแบบโครงสร้าง (Structural Engineer)\r\nวิศวกรโครงการ/ควบคุมงาน (Site Engineer)\r\nวิศวกรประมาณราคา (QS Engineer)', 'กรมโยธาธิการและผังเมือง / กรมชลประทาน\r\nกรมทางหลวง / กรมทางหลวงชนบท\r\nวิศวกรโยธาใน อบจ. และ เทศบาลทั่วประเทศ', 'Images-1778849584357-605105560.png', 'shopPhoto-1778849584361-762592691.jpg', 'pdfFiles-1778849584363-825331872.pdf,pdfFiles-1778849584373-55336370.pdf,pdfFiles-1778849584380-194244257.pdf', 1, '2026-05-15 19:53:04', NULL, NULL, 'fas fa-city'),
('CPE', 'สาขาวิชาวิศวกรรมคอมพิวเตอร์', 'Bachelor of Engineering Program in Computer Engineering', 'ภาควิชาวิศวกรรมไฟฟ้าและคอมพิวเตอร์', 'Computer Engineering (CPE)', 'ปริญญาตรี', 'หลักสูตรวิศวกรรมศาสตรบัณฑิต (วศ.บ.)', 'ข้าใจลึกซึ้ง: ไม่ใช่แค่ใช้คอมพิวเตอร์เป็น แต่ต้องเข้าใจระบบข้างในอย่างถ่องแท้\r\n\r\nวิเคราะห์และทำนาย: เรียนรู้การจัดการข้อมูล (Data) เพื่อนำมาวิเคราะห์และทำนายอนาคต (AI & Machine Learning)\r\n\r\nสร้างนวัตกรรมดิจิทัล: มุ่งเน้นการแก้ปัญหาโลกสมัยใหม่ด้วยเทคโนโลยีใหม่ๆ (Digital Transformation)\r\n\r\nความรอบรู้: ปูพื้นฐานเทคโนโลยีที่แน่นพอจะไปประยุกต์ต่อยอดได้ในทุกอุตสาหกรรม', 'การศึกษาด้านฮาร์ดแวร์: เรียนลึกถึงระบบคอมพิวเตอร์และอุปกรณ์คอมพิวเตอร์\r\nการสร้างซอฟต์แวร์ :เรียนการเขียนโปรแกรมเพื่อควบคุมฮาร์ดแวร์และประมวลผลข้อมูล\r\nระบบการสื่อสารและการประยุกต์ใช้ (Communication & Integration)\r\nเรียนการเชื่อมต่อกันระหว่างฮาร์ดแวร์ ซอฟต์แวร์ และเครือข่าย\r\nเน้นไปที่ \"ฮาร์ดแวร์ฝังตัวภายใน\" (Embedded Hardware) หรือบอร์ดวงจรต่างๆ\r\nคลาวด์คอมพิวติ้ง (Cloud Computing)', ' เรียนเน้นปฏิบัติจริงด้วย Project-Based Learning ในทุกชั้นปี\r\n\r\n ห้องปฏิบัติการคอมพิวเตอร์ที่ทันสมัย พร้อมอุปกรณ์ IoT และหุ่นยนต์ระดับสูง\r\n\r\n มีโอกาสสหกิจศึกษาใน Tech Company ชั้นนำระดับประเทศและต่างประเทศ\r\n\r\n สังคมรุ่นพี่รุ่นน้องดงตาลคอมพิวเตอร์ที่อบอุ่น พร้อมแชร์ประสบการณ์สายงานไอที', '', 'Software Engineer\r\nMobile Developer\r\nDevOps Engineer\r\nData Engineer\r\nAI / Machine Learning Engineer\r\nNetwork Engineer', 'การไฟฟ้า (EGAT, MEA, PEA)\r\nบริษัท ท่าอากาศยานไทย จำกัด (มหาชน) (AOT)\r\nธนาคารแห่งประเทศไทย (BOT) \r\nธนาคารรัฐ (กรุงไทย, ออมสิน, ธอส.)', 'Images-1783874852292-269145235.jpg', 'shopPhoto-1783874852367-417072107.jpg', 'pdfFiles-1783874852453-407359037.pdf,pdfFiles-1783874852456-52533515.pdf,pdfFiles-1783874852458-320692088.pdf', 1, '2026-07-12 23:47:32', NULL, NULL, 'fas fa-microchip'),
('CS', 'สาขาวิชาวิทยาการคอมพิวเตอร์', 'Bachelor of Science Program in Computer Science', 'ภาควิชาวิทยาการคอมพิวเตอร์และสารสนเทศ', 'Bachelor of Science in Computer Science (CS)', 'ปริญญาตรี', 'หลักสูตรวิทยาศาสตรบัณฑิต (วท.บ.)', 'เน้นการเขียนโปรแกรมและการแก้ปัญหาด้วยตรรกะ (Logic) ที่เข้มข้น มุ่งเน้นการประยุกต์ใช้เทคโนโลยีสมัยใหม่เข้ากับอุตสาหกรรมจริง โดยไม่ต้องเรียนวิชาพื้นฐานวิทยาศาสตร์บางตัวที่ไม่จำเป็น (เช่น เคมี) เพื่อเน้นหนักด้าน Computing โดยเฉพาะ', 'การพัฒนาซอฟต์แวร์และโมบายแอปพลิเคชัน\r\nปัญญาประดิษฐ์ (AI) และ Machine Learning\r\nวิทยาการข้อมูล (Data Science) & Big Data\r\nความมั่นคงปลอดภัยไซเบอร์ (Cybersecurity)\r\nระบบเครือข่ายและ Cloud Computing\r\nการพัฒนาเกมและมัลติมีเดีย\r\n', 'Practical Mindset: เรียนทฤษฎีควบคู่การปฏิบัติ ทำโปรเจกต์จริงในทุกปีการศึกษา\r\n\r\n KU Standard: ปริญญาบัตรจากมหาวิทยาลัยเกษตรศาสตร์ การันตีคุณภาพมาตรฐานสากล\r\n\r\n Co-operative Education: โอกาสฝึกงานในบริษัท Tech ยักษ์ใหญ่และ Startup ชั้นนำ\r\n\r\n Modern Facilities: ห้องปฏิบัติการคอมพิวเตอร์ที่ทันสมัย พร้อมอุปกรณ์ IoT และ AI', 'สาชาวิทยาการคอมพิวเตอร์ (Computer Science หรือ CS) จัดเป็นหนึ่งในสาขาที่มี อัตราการเติบโตสูงและเป็นที่ต้องการของตลาดแรงงานทั่วโลก เพราะแทบทุกองค์กรกำลังขับเคลื่อนด้วยเทคโนโลยี และยังเปิดโอกาสให้ทำงานแบบ Remote Work กับบริษัทต่างชาติได้อีกด้วย', 'Full-stack Developer / Programmer\r\nData Scientist / Data Engineer\r\nAI Developer / ML Engineer', 'นักวิชาการคอมพิวเตอร์\r\nSystem Analyst (นักวิเคราะห์ระบบ)\r\nNetwork & Security Administrator\r\n', 'Images-1783336695893-987551992.jpg', 'shopPhoto-1783336695905-44347494.jpg', 'pdfFiles-1783336695916-527137213.pdf,pdfFiles-1783336695925-845898429.pdf', 1, '2026-07-06 18:18:15', 1, '2026-09-18 22:17:15', 'fas fa-laptop-code'),
('ECE', 'สาขาวิชาวิศวกรรมไฟฟ้า', 'Bachelor of Engineering Program in Electrical Engineering', 'ภาควิชาวิศวกรรมไฟฟ้าและคอมพิวเตอร์', 'Electrical and Computer Engineering (ECE)', 'ปริญญาตรี', 'หลักสูตรวิศวกรรมศาสตรบัณฑิต (วศ.บ.)', 'เป็นหลักสูตรทางวิศวกรรมไฟฟ้าที่จัดทำและพัฒนาขึ้นเพื่อพัฒนาความรู้ความสามารถในหมวดของวิศวกรรมไฟฟ้า ทางด้านการวิเคราะห์ และปฏิบัติไปพร้อม ๆ กัน', 'วงจรไฟฟ้า\r\nการเกิดสนามไฟฟ้า สนามแม่เหล็ก และคลื่น\r\nอุปกรณ์อิเล็กทรอนิกส์ในชีวิตประจำวัน\r\nเครื่องกำเนิดไฟฟ้า มอเตอร์ และหม้อแปลง\r\nไฟฟ้าแรงสูง และสายฟ้าทางธรรมชาติ\r\nอุตสาหกรรมโรงไฟฟ้า และอื่นๆ', 'เรียนจบแล้วมีสิทธิ์สอบ ใบอนุญาตประกอบวิชาชีพวิศวกรรมควบคุม (ใบ กว.) สาขาวิศวกรรมไฟฟ้ากำลัง\r\n\r\n มีห้องปฏิบัติการที่ทันสมัย ทั้งด้านวงจรไฟฟ้า, เครื่องกลไฟฟ้า (มอเตอร์/หม้อแปลง)\r\n\r\n ใช้หลักสูตรมาตรฐานเดียวกับ มก. บางเขน และได้รับปริญญาบัตรของมหาวิทยาลัยเกษตรศาสตร์\r\n\r\n เครือข่ายศิษย์เก่าวิศวะ (ดงตาล) ที่เหนียวแน่นคอยซัพพอร์ต', '1. จบไปสามารถทำงานได้ทั้งเอกชนและราชการ\r\n\r\n2. วิศวกรไฟฟ้าในรัฐวิสาหกิจ (กฟผ. / กฟภ. / กฟน.) เป็นสายงานยอดฮิตของนิสิตวิศวะไฟฟ้า\r\n\r\n3. มีศิษย์เก่า ม.เกษตรศาสตร์ มากมายในทุกวงการ ที่พร้อมจะช่วยเหลือพี่น้องเสมอ', 'วิศวกรโรงงานและระบบอัตโนมัติ\r\nวิศวกรงานระบบอาคาร\r\nวิศวกรพลังงานสะอาด (Solar/Wind)', '3 การไฟฟ้า (กฟผ. / กฟภ. / กฟน.)\r\nวิศวกรไฟฟ้าในส่วนราชการ/กรมต่างๆ\r\nอาจารย์ / นักวิจัยด้านไฟฟ้า', 'Images-1783514309353-407898196.jpg', 'shopPhoto-1783340155424-456424819.jpg', 'pdfFiles-1783340440894-489752919.pdf,pdfFiles-1783340440899-941195723.pdf,pdfFiles-1783340440911-365918256.pdf', 1, '2026-07-08 19:38:29', NULL, NULL, 'fas fa-bolt'),
('EES', 'สาขาวิชาวิศวกรรมสิ่งแวดล้อมเพื่อการพัฒนาอย่างยั่งยืน', 'Bachelor of Engineering Program in Environmental Engineering for Sustainable Development', 'ภาควิชาวิศวกรรมโยธาและสิ่งแวดล้อม', 'Civil and Environmental Engineering (CEE)', 'ปริญญาตรี', 'หลักสูตรวิศวกรรมศาสตรบัณฑิต (วศ.บ.)', 'เน้นประสบการณ์จริง ด้เรียนรู้และปฏิบัติงานในสถานการณ์จริง ไม่ใช่แค่ในตำรา\r\n\r\n บูรณาการศาสตร ผสมผสานความรู้ทางไฟฟ้าเครื่องจักรและโครงสร้างพื้นฐานมา ประยุกต์ใช้ในงานระบบสิ่งแวดล้อม\r\n\r\n การบริหารงานก่อสร้าง: เรียนรู้วิธีบริหารโครงการด้านสิ่งแวดล้อมให้สำเร็จตามกำหนดและงบ ประมาณ', 'ระบบน้ำ: ทำน้ำประปา บำบัดน้ำเสีย และจัดการน้ำในระดับชุมชนและอุตสาหกรรม\r\nมลพิษทางอากาศ: การควบคุมฝุ่นควันและก๊าซพิษจากโรงงาน\r\nการจัดการของเสีย: การบริหารจัดการขยะมูลฝอยและกากของเสียอันตราย\r\nความยั่งยืน: การออกแบบระบบที่ลดผลกระทบต่อธรรมชาติและใช้ทรัพยากรให้คุ้มค่าที่สุด\r\nกฎหมายสิ่งแวดล้อม, มาตรฐานการระบายมลพิษ (ทิ้งน้ำ/ปล่อยอากาศ)\r\nการผลิตก๊าซชีวภาพจากน้ำเสีย , การเปลี่ยนขยะเป็นพลังงาน', 'การเรียน: คุณจะได้เข้าแล็บเพื่อตรวจวัดคุณภาพสิ่งแวดล้อม เช่น การหาค่า BOD/COD ในน้ำ (เพื่อดูว่าน้ำเสียแค่ไหน), การวัดปริมาณฝุ่น PM 2.5 ในอากาศ, หรือการวิเคราะห์สารปนเปื้อนในดิน\r\n\r\n การเรียน : คุณไม่ได้เรียนแค่บำบัดน้ำยังไง แต่เรียนว่า \"จะสร้างโรงบำบัดยังไงให้เสร็จตามเวลา และงบประมาณ\" * ทักษะ: การอ่านแบบทางวิศวกรรม, การประเมินราคาก่อสร้าง, และการคุมงาน ก่อสร้าง (Site Engineer) ซึ่งเป็นทักษะที่ทำให้เด็กที่นี่โดดเด่นกว่าสายวิทยาศาสตร์สิ่งแวดล้อมทั่วไป', 'ในยุคที่ทั่วโลกให้ความสำคัญกับ ESG (Environment, Social, Governance) และภาวะโลกร้อน วิศวกรสิ่งแวดล้อม จึงเป็นที่ต้องการตัวสูงมากในทุกภาคส่วน เพื่อทำให้ธุรกิจเดินหน้าไปได้โดยไม่ทำลายสิ่งแวดล้อม', 'วิศวกรสิ่งแวดล้อม\r\nบริษัทที่ปรึกษา\r\nผู้ควบคุมระบบงานก่อสร้าง', 'วิศวกรในกรมควบคุมมลพิษ\r\nกรมโรงงานอุตสาหกรรม\r\nกรมทรัพยากรน้ำ', 'Images-1783522744239-775995571.png', 'shopPhoto-1783522744245-182001400.jpg', 'pdfFiles-1783873769267-181643309.pdf', 1, '2026-07-08 21:59:04', NULL, NULL, 'fas fa-tree'),
('GE', 'สาขาวิชาเคมีประยุกต์', 'Bachelor of Science Program in Applied Chemistry', 'ภาควิชาวิทยาศาสตร์ทั่วไป', 'Applied Chemistry (General Science)', 'ปริญญาตรี', 'หลักสูตรวิทยาศาสตรบัณฑิต (วท.บ.)', '• เน้นการปฏิบัติจริง: มุ่งเน้นการฝึกฝนทักษะในห้องปฏิบัติการเพื่อให้เกิดความเชี่ยวชาญระดับมืออาชีพ\r\n\r\n• ประสบการณ์สายตรง: มีโครงการสหกิจศึกษา ให้นิสิตได้เข้าทำงานจริงในบริษัทหรือหน่วยงานชั้นนำก่อนจบการศึกษา\r\n\r\n• ประยุกต์ใช้ได้หลากหลาย: ต่อยอดความรู้ในอุตสาหกรรมเป้าหมาย เช่น อาหาร, ยา, เครื่องสำอาง, พลังงาน และสิ่งแวดล้อม', 'เคมีพื้นฐานและเทคนิคปฏิบัติ: ปูพื้นฐานการทำแล็บที่ถูกต้อง แม่นยำ และปลอดภัย\r\nเครื่องมือวิเคราะห์ทางเคมี: การใช้เครื่องมือขั้นสูง (Instrumental Analysis) ตรวจสอบองค์ประกอบสาร\r\nพอลิเมอร์และวัสดุศาสตร์: การสร้างและพัฒนาวัสดุใหม่ พลาสติก และยาง\r\nเคมีเกษตรและอาหาร: การวิเคราะห์สารตกค้างและพัฒนาผลิตภัณฑ์แปรรูป\r\nเครื่องสำอางและยา: เทคนิคการสกัดสารสำคัญและการควบคุมคุณภาพการผลิต\r\nโครงงานเคมีประยุกต์: ทำวิจัยแก้ปัญหาจริงในภาคอุตสาหกรรมหรือสร้างนวัตกรรมใหม่', '1. บรรยากาศการเรียน\r\nเรียนแบบใกล้ชิด อุปกรณ์วิเคราะห์ครบครัน ทันสมัย พร้อมใช้งานจริง\r\n\r\n2. การลงมือทำ\r\nเน้นการทดลองในห้องแล็บ เพื่อสร้างความคุ้นเคยกับเครื่องมือระดับอุตสาหกรรม\r\n\r\n3. โจทย์จากอุตสาหกรรม\r\nโปรเจกต์จบเน้นแก้ปัญหาจากโรงงานจริง ทำให้นิสิตเป็น Problem Solver\r\n\r\n4. เครือข่ายศิษย์เก่า\r\nมีรุ่นพี่คอยดูแลและให้คำแนะนำ ทั้งเรื่องการเรียนและการหางาน', '\"ทุกโรงงาน ทุกวงการ เคมีประยุกต์ล้วนมีที่ยืน\" ไม่ว่าเศรษฐกิจจะเป็นอย่างไร อุตสาหกรรมอาหาร ยา และการควบคุมมลพิษ ยังคงต้องการนักเคมีที่มีทักษะการปฏิบัติงานจริงเสมอ', 'นักเคมีควบคุมคุณภาพ (QC/QA)\r\nนักวิจัยและพัฒนาผลิตภัณฑ์ (R&D)\r\nเจ้าหน้าที่เทคนิค/ฝ่ายขายเครื่องมือวิทยาศาสตร์\r\nเจ้าหน้าที่สิ่งแวดล้อม/ความปลอดภัย (SHE)', 'นักวิทยาศาสตร์/นักวิจัย (กรมวิทยาศาสตร์บริการ)\r\nนักเคมี (การไฟฟ้าฝ่ายผลิตแห่งประเทศไทย/ปตท.)\r\nนักนิติวิทยาศาสตร์ (กองพิสูจน์หลักฐาน)\r\nอาจารย์/บุคลากรทางการศึกษา', 'Images-1783874211291-297943746.jpg', 'shopPhoto-1783874211296-426202781.jpg', 'pdfFiles-1783874211404-528437930.pdf,pdfFiles-1783874211409-866920020.pdf,pdfFiles-1783874211412-279234423.pdf', 1, '2026-07-12 23:36:51', 3, '2026-08-04 11:24:28', 'fas fa-flask'),
('MME', 'สาขาวิชาวิศวกรรมเครื่องกลและการผลิต', 'Bachelor of Engineering Program in Mechanical and Manufacturing Engineering', 'ภาควิชาวิศวกรรมเครื่องกลและการผลิต', 'Mechanical and Manufacturing Engineering (MME)', 'ปริญญาตรี', 'หลักสูตรวิศวกรรมศาสตรบัณฑิต (วศ.บ.)', 'รับรองโดยสภาวิศวกร (กว.): มีสิทธิ์สอบใบประกอบวิชาชีพวิศวกรรมควบคุม สาขาวิศวกรรมเครื่องกล\r\n\r\n เรียนจบได้ภายใน 3 ปีครึ่ง: เข้าสู่ตลาดแรงงานได้รวดเร็วกว่า ช่วยประหยัดเวลาและค่าใช้จ่าย\r\n\r\n เน้นทักษะงานช่างพื้นฐาน: ฝึกปฏิบัติจริงทั้งงานเชื่อม กลึง กัด ตัด ไส เจาะ และเจียระไน', 'การเขียนแบบ (Drawing) และกลศาสตร์\r\nการออกแบบชิ้นส่วนเครื่องจักรกล\r\nพลังงาน ความร้อน และระบบปรับอากาศ\r\nระบบอัตโนมัติและหุ่นยนต์ (Robot)\r\nการวางแผนผลิตและการควบคุมคุณภาพ\r\nวิศวกรรมยานยนต์และพลังงานทดแทน', ' สิทธิ์สอบ กว. : ใช้เซ็นรับรองแบบและคุมงานตามกฎหมายได้อย่างถูกต้อง\r\n\r\n Lab เฉพาะทาง : ห้องปฏิบัติการที่ทันสมัยซัพพอร์ตทั้งด้านเครื่องกลและอุตสาหการ\r\n\r\n การคิดวิเคราะห์ครบวงจร : สอนตั้งแต่การออกแบบ ติดตั้ง ไปจนถึงการบำรุงรักษา\r\n\r\n เครือข่ายรุ่นพี่ : สังคมที่เข้มแข็งคอยช่วยเหลือตั้งแต่วันแรกที่เรียนจนถึงวันทำงาน', '1. วิศวกรในบริษัทชั้นนำ: ทั้งบริษัทข้ามชาติและโรงงานอุตสาหกรรมขนาดใหญ่\r\n\r\n2. รัฐวิสาหกิจเกรด A: เช่น กฟผ. (EGAT), ปตท. (PTT) ซึ่งเป็นสายงานยอดนิยม\r\n\r\n3. สถิติการทำงาน: อัตราการได้งานทำสูงกว่า 90% และทำงานตรงสายงาน', 'วิศวกรออกแบบและผลิต (Design & Production)\r\nวิศวกรซ่อมบำรุง (Maintenance Engineer)\r\nวิศวกรโครงการ/งานระบบ (Project Engineer)', '3 การไฟฟ้า (กฟผ. / กฟภ. / กฟน.)\r\nที่ปรึกษาด้านพลังงานและวิศวกรโรงงาน\r\nอาจารย์ / นักวิจัย / รับราชการกรมต่างๆ', 'Images-1783522157537-376492045.jpg', 'shopPhoto-1783522157654-128842749.jpg', 'pdfFiles-1783522157795-483351377.pdf,pdfFiles-1783522157810-499188559.pdf,pdfFiles-1783522157821-686698040.pdf', 1, '2026-07-08 21:49:17', NULL, NULL, 'fas fa-gears');

